<template>
  <div class="mobile-dropdown" :class="[themeClass]" ref="dropdownRef">
    <!-- 触发器区域 -->
    <div 
      class="mobile-dropdown-trigger" 
      :class="{ 'is-active': isOpen }"
      @click="toggleDropdown"
    >
      <span class="trigger-text">{{ selectedOption?.label || computedPlaceholder }}</span>
      <div class="trigger-arrow" :class="{ 'is-flipped': isOpen }">
        <mobile-l-img :src="'/static/mobile_images/arrow-up.png'" w="12px" h="12px" />
      </div>
    </div>

    <!-- 下拉选项列表 -->
    <transition 
      :name="direction === 'up' ? 'slide-up' : 'slide-down'"
      @enter="onEnter"
      @leave="onLeave"
    >
      <div 
        v-show="isOpen" 
        class="mobile-dropdown-menu"
        :class="[`direction-${direction}`, { 'is-above': direction === 'up' }]"
        :style="menuStyle"
      >
        <div class="menu-container">
          <div 
            v-for="(option, index) in orderedOptions" 
            :key="option.value" 
            class="dropdown-option"
            :class="{ 'is-selected': option.value === selectedValue }"
            @click="selectOption(option)"
          >
            <!-- 插槽内容区域，优先级高于默认显示 -->
            <div class="option-content" :class="{ 'is-selected': option.value === selectedValue }">
              <slot 
                name="option" 
                :option="option" 
                :index="index" 
                :isSelected="option.value === selectedValue"
              >
                <!-- 默认内容：当没有提供插槽时显示 -->
                <span class="option-text" :class="{ 'is-selected': option.value === selectedValue }">{{ option.label }}</span>
              </slot>
            </div>
            
            <!-- 勾选图标区域：始终保留 -->
            <div v-if="option.value === selectedValue" class="option-check">
              <mobile-l-img 
                :src="theme === 'light' ? '/static/mobile_images/checked-blue.png' : '/static/mobile_images/checked-black.png'" 
                w="12px" 
                h="12px" 
              />
            </div>
          </div>
        </div>
      </div>
    </transition>

    <!-- 遮罩层 -->
    <div 
      v-show="isOpen" 
      class="mobile-dropdown-overlay" 
      @click="closeDropdown"
    ></div>
  </div>
</template>

<script setup>
// 引入区域
import { ref, computed, watch, nextTick, onMounted, onUnmounted } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';

// props区域
const props = defineProps({
  // 选项数据
  // 支持插槽自定义：可使用 #option="{ option, index, isSelected }" 插槽自定义选项内容
  options: {
    type: Array,
    default: () => [],
    required: true
  },
  // 当前选中值
  modelValue: {
    type: [String, Number],
    default: null
  },
  // 占位符文本
  placeholder: {
    type: String,
    default: ''
  },
  // 主题类型：light（亮色）、dark（暗色）
  theme: {
    type: String,
    default: 'light',
    validator: value => ['light', 'dark'].includes(value)
  },
  // 展开方向：up（向上）、down（向下）
  direction: {
    type: String,
    default: 'down',
    validator: value => ['up', 'down'].includes(value)
  },
  // 偏移量（像素）
  offset: {
    type: Number,
    default: 5
  },
  // 是否禁用
  disabled: {
    type: Boolean,
    default: false
  }
});

// emits区域
const emit = defineEmits(['update:modelValue', 'onChange']);

// 变量区域
const { t } = useI18n();
const dropdownRef = ref(null);
const isOpen = ref(false);
const selectedValue = ref(props.modelValue);

// 计算属性区域
const themeClass = computed(() => `theme-${props.theme}`);

const selectedOption = computed(() => {
  return props.options.find(option => option.value === selectedValue.value);
});

const orderedOptions = computed(() => {
  // 上方模式时选项倒序
  return props.direction === 'up' ? [...props.options].reverse() : props.options;
});

const computedPlaceholder = computed(() => {
  return props.placeholder || t('pleaseSelect');
});

const menuStyle = computed(() => {
  const offsetValue = `${props.offset}px`;
  return props.direction === 'up' 
    ? { bottom: `calc(100% + ${offsetValue})` }
    : { top: `calc(100% + ${offsetValue})` };
});

// watch区域
watch(() => props.modelValue, (newValue) => {
  selectedValue.value = newValue;
});

watch(selectedValue, (newValue) => {
  emit('update:modelValue', newValue);
});

// 点击事件区域
const toggleDropdown = () => {
  if (props.disabled) return;
  isOpen.value = !isOpen.value;
};

const closeDropdown = () => {
  isOpen.value = false;
};

// 自定义事件区域
const onEnter = (el) => {
  el.style.height = '0';
  el.offsetHeight; // 强制重绘
  el.style.height = el.scrollHeight + 'px';
};

const onLeave = (el) => {
  el.style.height = el.scrollHeight + 'px';
  el.offsetHeight; // 强制重绘
  el.style.height = '0';
};

// 业务逻辑区域
const selectOption = (option) => {
  selectedValue.value = option.value;
  emit('onChange', option);
  closeDropdown();
};

const handleClickOutside = (event) => {
  if (dropdownRef.value && !dropdownRef.value.contains(event.target)) {
    closeDropdown();
  }
};

// 初始化方法区域
const initEvent = () => {
  document.addEventListener('click', handleClickOutside);
};

const removeEvent = () => {
  document.removeEventListener('click', handleClickOutside);
};

// 周期函数区域
onMounted(() => {
  initEvent();
});

onUnmounted(() => {
  removeEvent();
});

// 导出区域
defineExpose({
  close: closeDropdown,
  open: () => {
    if (!props.disabled) {
      isOpen.value = true;
    }
  }
});
</script>

