<template>
  <div class="mobile-slider-input__container">
    <span class="mobile-slider-input__label mobile-slider-input__label--min" v-if="showLabels">{{ formatValue(min) }}</span>
    <!-- 原生 input range -->
    <input
      ref="inputRef"
      type="range"
      class="mobile-slider-input__input"
      :min="min"
      :max="max"
      :step="step"
      :value="currentValue"
      :disabled="disabled"
      @input="onInput"
      @change="onChange"
    />
    <span class="mobile-slider-input__label mobile-slider-input__label--max" v-if="showLabels">{{ formatValue(max) }}</span>
    
    <!-- 当前值显示器 -->
    <div 
      v-if="showCurrentValue"
      class="mobile-slider-input__current-value"
      :style="valuePositionStyle"
    >
      {{ formatValue(currentValue) }}
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue';

// props区域
const props = defineProps({
  currentValue: {
    type: Number,
    default: 0
  },
  min: {
    type: Number,
    default: 0
  },
  max: {
    type: Number,
    default: 100
  },
  step: {
    type: Number,
    default: 1
  },
  disabled: {
    type: Boolean,
    default: false
  },
  showLabels: {
    type: Boolean,
    default: true
  },
  showCurrentValue: {
    type: Boolean,
    default: false
  },
  precision: {
    type: Number,
    default: 2
  }
});

// emits区域
const emit = defineEmits(['onInput', 'onChange']);

// 变量区域
const inputRef = ref(null);
const inputMetrics = ref({
  offsetLeft: 0,
  width: 0
});

// 业务逻辑区域
const updateProgressStyle = () => {
  if (inputRef.value && !props.disabled) {
    const percentage = valuePercentage.value * 100;
    // 直接在input上设置背景渐变实现进度条效果
    inputRef.value.style.background = `linear-gradient(
      to right, 
      #2563EB 0%, 
      #2563EB ${percentage}%, 
      #DBEAFE ${percentage}%, 
      #DBEAFE 100%
    )`;
  }
};

const updateInputMetrics = () => {
  if (inputRef.value && inputRef.value.parentElement) {
    const containerRect = inputRef.value.parentElement.getBoundingClientRect();
    const inputRect = inputRef.value.getBoundingClientRect();
    
    inputMetrics.value = {
      offsetLeft: inputRect.left - containerRect.left,
      width: inputRect.width
    };
  }
};

// 计算属性区域
const valueRange = computed(() => props.max - props.min);

const valuePercentage = computed(() => {
  if (valueRange.value === 0) return 0;
  return Math.max(0, Math.min(1, (props.currentValue - props.min) / valueRange.value));
});

const valuePositionStyle = computed(() => {
  // 计算当前值显示器的位置
  const percentage = valuePercentage.value;
  
  // 基于存储的input元素度量信息计算
  if (inputMetrics.value.width > 0) {
    // 滑块手柄在input中的精确位置
    const thumbPosition = inputMetrics.value.offsetLeft + inputMetrics.value.width * percentage;
    
    return {
      left: `${thumbPosition}px`,
      transform: 'translateX(-50%)'
    };
  }
  
  // 降级方案：如果还未测量，使用估算值
  return {
    left: `calc(50% * ${percentage + 1})`,
    transform: 'translateX(-50%)'
  };
});

// watch区域
watch(
  () => props.currentValue,
  () => {
    updateProgressStyle();
    updateInputMetrics();
  },
  { immediate: true }
);

// 自定义事件区域
const onInput = (event) => {
  const newValue = parseFloat(event.target.value);
  emit('onInput', newValue);
  updateProgressStyle();
  
  // 确保度量信息是最新的
  updateInputMetrics();
};

const onChange = (event) => {
  const newValue = parseFloat(event.target.value);
  emit('onChange', newValue);
};

// resize事件处理函数
const handleResize = () => {
  updateInputMetrics();
};

// 数据解析区域
const formatValue = (value) => {
  return Number(value).toFixed(props.precision);
};

// 初始化方法区域
const initMetrics = () => {
  nextTick(() => {
    updateInputMetrics();
  });
};

// 周期函数区域
onMounted(() => {
  updateProgressStyle();
  initMetrics();
  
  // 监听窗口大小变化，重新测量
  window.addEventListener('resize', handleResize);
});

onUnmounted(() => {
  window.removeEventListener('resize', handleResize);
});

// 导出区域
defineExpose({
  updateInputMetrics,
  updateProgressStyle,
  initMetrics
});
</script>

